#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> part1, part2;
    int midpoint = n / 2;

    function<void(int, int)> build_part1 = [&](int i, int total) {
        if (i == midpoint) {
            part1.push_back(total);
        } else {
            build_part1(i + 1, (total + a[i]) % m);
            build_part1(i + 1, total);
        }
    };

    function<void(int, int)> build_part2 = [&](int i, int total) {
        if (i == n) {
            part2.push_back(total);
        } else {
            build_part2(i + 1, (total + a[i]) % m);
            build_part2(i + 1, total);
        }
    };

    build_part1(0, 0);
    build_part2(midpoint, 0);

    std::set<int> unique_part1_set(part1.begin(), part1.end());
    std::vector<int> unique_part1(unique_part1_set.begin(), unique_part1_set.end());
    int best_sum = 0;

    for (int val : part2) {
        int index = (int)std::lower_bound(unique_part1.begin(), unique_part1.end(), m - val) - unique_part1.begin();
        if (index > 0) {
            int candidate_sum = unique_part1[index - 1] + val;
            if (candidate_sum > best_sum) {
                best_sum = candidate_sum;
            }
        }
    }

    cout << best_sum << "\n";

    return 0;
}
